// Import of required libraries
import { test, expect, SkyrampClient, getBaseUrl, getValue, getResponseValue, uniqueSuffix } from '@skyramp/skyramp';
import { createCollection, createUser, updateCollection, getCollectionMembers, deleteCollectionMember, deleteUser, deleteCollection } from './skyrampUtils';

// URL for test requests
const URL_localhost = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:3000");

test('testIntegration', async () => {
    test.setTimeout(60000);

    // Invocation of Skyramp Client
    const client = new SkyrampClient();
    // Definition of authentication header
    const headers: Record<string, string> = {};
    if (process.env.SKYRAMP_TEST_TOKEN && process.env.SKYRAMP_TEST_TOKEN != "") {
        headers["Authorization"] = "Bearer " + process.env.SKYRAMP_TEST_TOKEN;
    }

    const collectionsPostResponse = await createCollection(client, URL_localhost, headers, "tb-members-lifecycle");
    expect(getResponseValue(collectionsPostResponse, "response.name"), 'name').toBe("tb-members-lifecycle");
    const collectionId = getResponseValue(collectionsPostResponse, "response.id");
    expect(collectionId, 'id').toBeGreaterThan(0);
    expect(getResponseValue(collectionsPostResponse, "response.members").length, 'a new collection starts with no members').toBe(0);

    const usersPostResponse = await createUser(client, URL_localhost, headers, "TB Member", "tbmember", "tbmember@example.com", "tbmemberpassword123");
    // An admin-authenticated create returns the narrow admin shape: id, username, email,
    // emailVerified, subscriptions, createdAt — no name field.
    expect(getResponseValue(usersPostResponse, "response.username"), 'username').toMatch(/^tbmember-\d+$/);
    expect(getResponseValue(usersPostResponse, "response.email"), 'no email provider is configured, so email is not stored').toBeNull();
    const memberUserId = getResponseValue(usersPostResponse, "response.id");
    expect(memberUserId, 'id').toBeGreaterThan(0);

    // Seed the membership row through the existing collection update route.
    const collectionsCollectionsPutResponse = await updateCollection(client, URL_localhost, headers, collectionId, "tb-members-lifecycle", memberUserId);
    expect(getResponseValue(collectionsCollectionsPutResponse, "response.members").length, 'members').toBe(1);
    expect(getResponseValue(collectionsCollectionsPutResponse, "response.members.0.userId"), 'members.0.userId').toBe(memberUserId);
    expect(getResponseValue(collectionsCollectionsPutResponse, "response.members.1"), 'there is no second member').toBeNull();

    // The new endpoint lists that member with their embedded user record.
    const membersGetResponse = await getCollectionMembers(client, URL_localhost, headers, collectionId);
    expect(getResponseValue(membersGetResponse, "response").length, 'exactly the one seeded member').toBe(1);
    expect(getResponseValue(membersGetResponse, "response.0.userId"), 'response.0.userId').toBe(memberUserId);
    expect(getResponseValue(membersGetResponse, "response.0.collectionId"), 'response.0.collectionId').toBe(collectionId);
    expect(getResponseValue(membersGetResponse, "response.0.canCreate"), 'response.0.canCreate').toBe(false);
    expect(getResponseValue(membersGetResponse, "response.0.canUpdate"), 'response.0.canUpdate').toBe(false);
    expect(getResponseValue(membersGetResponse, "response.0.canDelete"), 'response.0.canDelete').toBe(false);
    expect(getResponseValue(membersGetResponse, "response.0.user.id"), 'response.0.user.id').toBe(memberUserId);
    expect(getResponseValue(membersGetResponse, "response.0.user.name"), 'response.0.user.name').toBe("TB Member");
    expect(getResponseValue(membersGetResponse, "response.1"), 'there is no second member').toBeNull();

    // Removing that member by userId succeeds.
    const membersDeleteResponse = await deleteCollectionMember(client, URL_localhost, headers, collectionId, {"userId": [memberUserId]});
    expect(getResponseValue(membersDeleteResponse, "response"), 'response').toBe("Member removed.");

    // The list is empty afterwards.
    const membersGet1Response = await getCollectionMembers(client, URL_localhost, headers, collectionId);
    expect(membersGet1Response.statusCode, 'status code').toBe(200);
    expect(getResponseValue(membersGet1Response, "response").length, 'the removed member is gone').toBe(0);
    expect(getResponseValue(membersGet1Response, "response.0"), 'response.0').toBeNull();

    await deleteUser(client, URL_localhost, headers, memberUserId);
    await deleteCollection(client, URL_localhost, headers, collectionId);
});
